import { useEffect, useMemo, useState } from "react";
import { Link, useNavigate } from "react-router-dom";

const EMPTY_PRODUCT = { name: "", brand: "", description: "", categoryId: "", price: "", originalPrice: "", stock: "0", sizes: "", colors: "", image: "" };
const API_URL = import.meta.env.VITE_API_URL || "http://localhost:8000";

function request(path, options = {}) {
  const token = localStorage.getItem("authToken");
  return fetch(`${API_URL}${path}`, { ...options, headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...options.headers } });
}

export default function VendorDashboard() {
  const navigate = useNavigate();
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [metrics, setMetrics] = useState(null);
  const [form, setForm] = useState(EMPTY_PRODUCT);
  const [editingId, setEditingId] = useState(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const displayName = useMemo(() => JSON.parse(localStorage.getItem("authUser") || "{}"), []);
  async function load() {
    setLoading(true);
    try {
      const [dashboardResponse, categoriesResponse, productsResponse] = await Promise.all([request("/vendor/dashboard/"), request("/vendor/categories/"), request("/vendor/products/")]);
      if ([dashboardResponse, categoriesResponse, productsResponse].some((response) => response.status === 401 || response.status === 403)) { navigate("/login", { replace: true }); return; }
      const [dashboard, categoryData, productData] = await Promise.all([dashboardResponse.json(), categoriesResponse.json(), productsResponse.json()]);
      if (!dashboardResponse.ok || !categoriesResponse.ok || !productsResponse.ok) throw new Error(dashboard.error || categoryData.error || productData.error || "Unable to load your dashboard");
      setMetrics(dashboard.metrics); setCategories(categoryData.categories); setProducts(productData.products);
    } catch (err) { setError(err.message); } finally { setLoading(false); }
  }
  useEffect(() => { load(); }, []);
  function updateForm(event) { setForm((current) => ({ ...current, [event.target.name]: event.target.value })); }
  function selectProduct(product) { setEditingId(product.id); setForm({ name: product.name, brand: product.brand, description: product.description, categoryId: String(product.categoryId), price: String(product.price), originalPrice: product.originalPrice || "", stock: String(product.stock), sizes: product.sizes.join(", "), colors: product.colors.join(", "), image: product.image }); window.scrollTo({ top: 0, behavior: "smooth" }); }
  async function submit(event) {
    event.preventDefault(); setError(""); setMessage("");
    const payload = { ...form, categoryId: Number(form.categoryId), price: Number(form.price), originalPrice: form.originalPrice ? Number(form.originalPrice) : null, stock: Number(form.stock), sizes: form.sizes.split(",").map((item) => item.trim()).filter(Boolean), colors: form.colors.split(",").map((item) => item.trim()).filter(Boolean) };
    try {
      const response = await request(editingId ? `/vendor/products/${editingId}/` : "/vendor/products/", { method: editingId ? "PUT" : "POST", body: JSON.stringify(payload) });
      const data = await response.json(); if (!response.ok) throw new Error(data.error || "Unable to save product");
      setMessage(data.message); setForm(EMPTY_PRODUCT); setEditingId(null); load();
    } catch (err) { setError(err.message); }
  }
  async function removeProduct(id) { if (!window.confirm("Delete this product permanently?")) return; const response = await request(`/vendor/products/${id}/`, { method: "DELETE" }); const data = await response.json(); if (!response.ok) setError(data.error || "Unable to delete product"); else { setMessage(data.message); load(); } }
  function logout() { localStorage.removeItem("authToken"); localStorage.removeItem("authUser"); navigate("/login"); }
  const cards = metrics ? [["Products", metrics.totalProducts], ["In stock units", metrics.inventoryUnits], ["Approved", metrics.approvedProducts], ["Awaiting review", metrics.pendingProducts]] : [];
  return <div className="min-h-screen bg-ivory text-ink"><header className="border-b border-gold-soft bg-ivory"><div className="mx-auto flex max-w-7xl items-center justify-between px-6 py-5"><Link to="/vendor" className="font-serif text-3xl font-semibold">Divishaa <span className="text-gold">.couture</span></Link><div className="flex items-center gap-4"><span className="hidden text-sm text-gray sm:block">Vendor portal · {displayName.firstName || "Account"}</span><button onClick={logout} className="border border-gold-soft px-4 py-2 text-xs uppercase tracking-widest hover:bg-ink hover:text-ivory">Sign out</button></div></div></header><main className="mx-auto max-w-7xl px-6 py-10"><p className="text-xs uppercase tracking-[0.25em] text-gold">Vendor workspace</p><h1 className="mt-2 font-serif text-4xl">Manage your collection</h1><p className="mt-2 text-gray">Add products, track approval status, and keep your inventory current.</p>{error && <p className="mt-6 border border-maroon/30 bg-maroon/5 px-4 py-3 text-sm text-maroon">{error}</p>}{message && <p className="mt-6 border border-emerald-700/30 bg-emerald-50 px-4 py-3 text-sm text-emerald-800">{message}</p>}<section className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{cards.map(([label, value]) => <div key={label} className="border border-gold-soft bg-white/50 p-5"><p className="text-xs uppercase tracking-widest text-gray">{label}</p><p className="mt-2 font-serif text-4xl">{value}</p></div>)}</section><div className="mt-10 grid gap-10 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)]"><section className="border border-gold-soft bg-white/50 p-6"><h2 className="font-serif text-3xl">{editingId ? "Edit product" : "Add a product"}</h2><p className="mt-1 text-sm text-gray">New and edited products are sent for approval.</p><form onSubmit={submit} className="mt-6 space-y-4"><input required name="name" value={form.name} onChange={updateForm} placeholder="Product name" className="w-full border border-gold-soft bg-transparent px-3 py-2.5 text-sm focus:border-ink focus:outline-none" /><div className="grid gap-4 sm:grid-cols-2"><input name="brand" value={form.brand} onChange={updateForm} placeholder="Brand" className="border border-gold-soft bg-transparent px-3 py-2.5 text-sm focus:border-ink focus:outline-none" /><select required name="categoryId" value={form.categoryId} onChange={updateForm} className="border border-gold-soft bg-transparent px-3 py-2.5 text-sm focus:border-ink focus:outline-none"><option value="">Select category</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div><textarea name="description" value={form.description} onChange={updateForm} placeholder="Description" rows="3" className="w-full border border-gold-soft bg-transparent px-3 py-2.5 text-sm focus:border-ink focus:outline-none" /><div className="grid gap-4 sm:grid-cols-3"><input required min="0" type="number" name="price" value={form.price} onChange={updateForm} placeholder="Price" className="border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /><input min="0" type="number" name="originalPrice" value={form.originalPrice} onChange={updateForm} placeholder="Original price" className="border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /><input required min="0" type="number" name="stock" value={form.stock} onChange={updateForm} placeholder="Stock" className="border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /></div><input name="sizes" value={form.sizes} onChange={updateForm} placeholder="Sizes, comma separated (S, M, L)" className="w-full border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /><input name="colors" value={form.colors} onChange={updateForm} placeholder="Colors, comma separated" className="w-full border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /><input type="url" name="image" value={form.image} onChange={updateForm} placeholder="Main image URL" className="w-full border border-gold-soft bg-transparent px-3 py-2.5 text-sm" /><div className="flex gap-3"><button className="bg-ink px-5 py-3 text-xs uppercase tracking-widest text-ivory hover:bg-maroon">{editingId ? "Save changes" : "Submit product"}</button>{editingId && <button type="button" onClick={() => { setEditingId(null); setForm(EMPTY_PRODUCT); }} className="border border-gold-soft px-5 py-3 text-xs uppercase tracking-widest">Cancel</button>}</div></form></section><section><div className="flex items-end justify-between"><div><h2 className="font-serif text-3xl">Your products</h2><p className="mt-1 text-sm text-gray">Only you can change these listings.</p></div></div>{loading ? <p className="mt-6 text-gray">Loading products…</p> : <div className="mt-6 space-y-3">{products.length === 0 ? <div className="border border-dashed border-gold-soft p-8 text-center text-gray">No products yet. Add your first product from the form.</div> : products.map((product) => <article key={product.id} className="flex gap-4 border border-gold-soft bg-white/50 p-4">{product.image ? <img src={product.image} alt="" className="h-20 w-16 object-cover" /> : <div className="h-20 w-16 bg-ivory-deep" />}<div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><h3 className="font-medium">{product.name}</h3><span className="text-xs uppercase tracking-wider text-gold">{product.status}</span></div><p className="mt-1 text-sm text-gray">₹{product.price.toLocaleString("en-IN")} · {product.stock} in stock · {product.categoryName}</p><div className="mt-3 flex gap-4 text-xs uppercase tracking-wider"><button onClick={() => selectProduct(product)} className="text-ink underline underline-offset-4">Edit</button><button onClick={() => removeProduct(product.id)} className="text-maroon underline underline-offset-4">Delete</button></div></div></article>)}</div>}</section></div></main></div>;
}
